import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log


def test_parse_trims_fields_and_skips_comments_and_blank_lines():
    lines = ["   # comment", "", " \t ", " a , 2 , 0 ", "b, 1, "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 1, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["too,few", "too,many,fields,here", "x,today,1"])
def test_parse_reports_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", "a,1,1", "  # skipped", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts_survivors():
    events = parse_session_log(["b,5,1", "c,1,0", "b,2,0", "a,2,1"])
    assert dedupe_sessions(events) == [events[1], events[3], events[2]]


def test_daily_counts_include_only_conversions_in_range():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1", "f,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 3, 2) == []
